changeSet.sql:
CREATE OR ALTER TRIGGER trg_question_denorm ON question AFTER INSERT, DELETE AS BEGIN DECLARE @AffectedQuizzes TABLE (quiz_id BIGINT);
INSERT INTO @AffectedQuizzes (quiz_id) SELECT quiz_id FROM inserted UNION SELECT quiz_id FROM deleted;
UPDATE q SET q.total_questions = ( SELECT COUNT(*) FROM question qn WHERE qn.quiz_id = q.id ) FROM quiz q INNER JOIN @AffectedQuizzes aq ON q.id = aq.quiz_id; END;
